-- Nova schema for postgresql. Generated by: flask --app app schema-sql --dialect postgresql

-- The app creates and upgrades these tables itself on start (flask --app app migrate); versioned data

-- migrations are recorded in schema_migrations.

CREATE TABLE absences (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	person_email VARCHAR(255) NOT NULL, 
	person_name VARCHAR(200), 
	start_date VARCHAR(10) NOT NULL, 
	end_date VARCHAR(10) NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	source VARCHAR(16) NOT NULL, 
	source_ref VARCHAR(500), 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_absences_user_id ON absences (user_id);

CREATE TABLE action_items (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	title VARCHAR(500) NOT NULL, 
	owner VARCHAR(255), 
	due_at BIGINT, 
	source VARCHAR(16) NOT NULL, 
	source_ref VARCHAR(500), 
	status VARCHAR(8) NOT NULL, 
	created_at BIGINT NOT NULL, 
	done_at BIGINT, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_action_items_user_id ON action_items (user_id);

CREATE TABLE attachments (
	id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	message_id VARCHAR(36), 
	mime VARCHAR(32) NOT NULL, 
	data BYTEA NOT NULL, 
	size INTEGER NOT NULL, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_attachments_message_id ON attachments (message_id);

CREATE INDEX ix_attachments_user_id ON attachments (user_id);

CREATE TABLE audit_log (
	id VARCHAR(36) NOT NULL, 
	created_at BIGINT NOT NULL, 
	actor_id VARCHAR(36), 
	action VARCHAR(64) NOT NULL, 
	target_type VARCHAR(32), 
	target_id VARCHAR(64), 
	ip VARCHAR(64), 
	detail TEXT, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_audit_log_action ON audit_log (action);

CREATE INDEX ix_audit_log_actor_id ON audit_log (actor_id);

CREATE INDEX ix_audit_log_created_at ON audit_log (created_at);

CREATE TABLE channel_events (
	id VARCHAR(255) NOT NULL, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_channel_events_created_at ON channel_events (created_at);

CREATE TABLE channel_link_codes (
	id VARCHAR(64) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	channel VARCHAR(16) NOT NULL, 
	expires_at BIGINT NOT NULL, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_channel_link_codes_user_id ON channel_link_codes (user_id);

CREATE TABLE channel_state (
