	value VARCHAR(255), 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (key)
);

CREATE TABLE channel_threads (
	id VARCHAR(255) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	conversation_id VARCHAR(36) NOT NULL, 
	created_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_channel_threads_created_at ON channel_threads (created_at);

CREATE INDEX ix_channel_threads_user_id ON channel_threads (user_id);

CREATE TABLE conversations (
	id VARCHAR(36) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	user_id VARCHAR(36), 
	pinned INTEGER DEFAULT '0' NOT NULL, 
	archived INTEGER DEFAULT '0' NOT NULL, 
	summary TEXT, 
	summary_upto BIGINT, 
	subject_id VARCHAR(36), 
	created_at BIGINT NOT NULL, 
	updated_at BIGINT NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_conversations_user_id ON conversations (user_id);

CREATE INDEX ix_conversations_user_updated ON conversations (user_id, updated_at);

CREATE TABLE doc_chunks (
	id VARCHAR(36) NOT NULL, 
