	embedding BYTEA, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_doc_chunks_document_id ON doc_chunks (document_id);

CREATE INDEX ix_doc_chunks_user_id ON doc_chunks (user_id);

CREATE TABLE documents (
